import{_ as t,a,b as o,c as r,d as n,e as i,f as s,g as l}from"./chunks/update-robot-usb-5.Bdu86dZI.js";import{_ as d,o as c,c as p,a5 as h}from"./chunks/framework.DGp912Ge.js";const U=JSON.parse('{"title":"Software Update over USB","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/usb-software-update.md","filePath":"manual/gui/usb-software-update.md","lastUpdated":1785806767000}'),g={name:"manual/gui/usb-software-update.md"};function f(u,e,m,b,v,y){return c(),p("div",null,[...e[0]||(e[0]=[h('<h1 id="software-update-over-usb" tabindex="-1">Software Update over USB <a class="header-anchor" href="#software-update-over-usb" aria-label="Permalink to &quot;Software Update over USB&quot;">​</a></h1><p>This page explains how to update the GUI and the robot software from a USB drive, for closed networks with no internet access. You stage the installer files on a USB drive from an internet-connected PC, then plug that drive into the Steam Deck or tablet you want to update.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>A USB update replaces the <strong>internet connection only</strong>. To update the robot software, the GUI must still be <strong>connected to the robot over Wi-Fi</strong>. Installing the GUI app alone does not require a robot connection.</p></div></div><h2 id="prepare-usb" tabindex="-1">Step 1. Stage the files on the USB drive <a class="header-anchor" href="#prepare-usb" aria-label="Permalink to &quot;Step 1. Stage the files on the USB drive {#prepare-usb}&quot;">​</a></h2><p>On an internet-connected PC, plug in the USB drive and create an <code>RBQGUI</code> folder at its root. Inside it, create a <code>v{version}</code> folder named after the version you want to install.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+t+'" alt="Version folders inside the RBQGUI folder on a USB drive" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Version folders inside RBQGUI</figcaption></figure><p>Download the two files for that version into the version folder. Both are available from the <a href="/RBQ/manual/downloads/">Downloads</a> page.</p><table tabindex="0"><thead><tr><th style="text-align:left;">File</th><th style="text-align:left;">Purpose</th><th style="text-align:left;">Where to get it</th></tr></thead><tbody><tr><td style="text-align:left;"><code>RBQ-{version}.tar.gz</code></td><td style="text-align:left;">Robot software</td><td style="text-align:left;"><code>Source code (tar.gz)</code> on the release</td></tr><tr><td style="text-align:left;"><code>RBQGUI.apk</code></td><td style="text-align:left;">GUI app</td><td style="text-align:left;">Release attachment</td></tr></tbody></table><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="The tar.gz and apk files inside a version folder" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Installer files inside a version folder</figcaption></figure><p>Staging several versions in advance lets you pick the one you need in the field.</p><h2 id="scan-usb" tabindex="-1">Step 2. Plug in the drive and scan for versions <a class="header-anchor" href="#scan-usb" aria-label="Permalink to &quot;Step 2. Plug in the drive and scan for versions {#scan-usb}&quot;">​</a></h2><p>Plug the prepared USB drive into the Steam Deck or tablet you want to update, then press <strong><code>USB</code></strong> on the <code>Software Update</code> screen.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+o+'" alt="The USB button on the Software Update screen" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">USB button</figcaption></figure><p>The log pane reports how many versions the scan found.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+r+'" alt="Scan result shown in the log pane" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Scan complete</figcaption></figure><h2 id="select-version" tabindex="-1">Step 3. Select the version to install <a class="header-anchor" href="#select-version" aria-label="Permalink to &quot;Step 3. Select the version to install {#select-version}&quot;">​</a></h2><p>Open the version dropdown and select the version you want. Versions found on the USB drive are marked <strong><code>[USB]</code></strong>.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+n+'" alt="Version list with [USB] markers" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Selecting a version found on USB</figcaption></figure><p>Everything up to this point is the same for both updates. The steps below differ by target.</p><h2 id="install-gui" tabindex="-1">Step 4 (GUI). Install the GUI app <a class="header-anchor" href="#install-gui" aria-label="Permalink to &quot;Step 4 (GUI). Install the GUI app {#install-gui}&quot;">​</a></h2><p>Press <strong><code>Install App</code></strong> to install the GUI from <code>RBQGUI.apk</code> on the drive.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+i+'" alt="Install App button" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Install App</figcaption></figure><p>When the install finishes, check that <code>RBQGUI</code> under <code>Current Software Version</code> at the top of the screen now shows the version you installed.</p><h2 id="update-robot" tabindex="-1">Step 4 (Robot). Send the robot software <a class="header-anchor" href="#update-robot" aria-label="Permalink to &quot;Step 4 (Robot). Send the robot software {#update-robot}&quot;">​</a></h2><p>Press <strong><code>Update Robot</code></strong>. The <code>RBQ-{version}.tar.gz</code> file is copied from the drive to the device, then transferred to the robot.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+s+'" alt="Update Robot button" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Update Robot</figcaption></figure><p>When the transfer completes, a success message appears along with a <strong><code>Restart Robot</code></strong> button. The log shows the copy-from-USB step followed by the transfer to the robot.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+l+'" alt="Restart Robot button shown after a completed transfer" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Transfer complete · Restart Robot</figcaption></figure><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Put the robot in the <strong>sitting</strong> state before restarting, and do not move it until the restart finishes.</p></div></div><p>Restart the robot with <code>Restart Robot</code>, then check that <code>ROBOT</code> under <code>Current Software Version</code> now shows the version you installed.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The version folder name must start with <code>v</code> and match the version in the <code>tar.gz</code> filename inside it.</li><li>Updating the robot requires the GUI to be connected to the robot. Installing the GUI app does not.</li><li>If <code>EMERGENCY</code> appears during an update, check safety immediately.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Topic</th><th style="text-align:left;">Link</th></tr></thead><tbody><tr><td style="text-align:left;">GUI update over the internet</td><td style="text-align:left;"><a href="/RBQ/manual/gui/gui-software-update.html">GUI Software Update</a></td></tr><tr><td style="text-align:left;">Robot update over the internet</td><td style="text-align:left;"><a href="/RBQ/manual/gui/robot-software-update.html">Robot Software Update</a></td></tr></tbody></table>',34)])])}const w=d(g,[["render",f]]);export{U as __pageData,w as default};
